arguments.command:
python3 << 'EOF'
import csv

rows = list(csv.DictReader(open('dataset/temperature_logs.csv')))
print("total rows:", len(rows))
zones = {}
for r in rows:
    zones.setdefault(r['zone'], 0)
    zones[r['zone']] += 1
print("zones:", zones)

def parse_t(s):
    return float(s.replace(',', '.'))

# per zone, print min/max and any excursions beyond safe limits
# safe: Frozen <= -10, Meat <= 4, Dairy <= 6, Dry <= 35
limits = {'frozen': -10, 'meat': 4, 'dairy': 6, 'dry': 35}
for r in rows:
    z = r['zone'].lower()
    t = parse_t(r['temperature_c'])
    if t > limits[z]:
        print("EXCURSION:", r['timestamp'], r['zone'], t)
EOF

